// Hand-written. Not generated by Speakeasy.
package provider

import (
	"testing"

	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func TestImportedKeySetFormattingDoesNotPlanAnUpdate(t *testing.T) {
	for _, name := range []string{"jwks", "federation_jwks", "credential_jwks"} {
		t.Run(name, func(t *testing.T) {
			types := map[string]tftypes.Type{name: tftypes.String, "computed": tftypes.String}
			state := obj(types, map[string]tftypes.Value{
				name:       tftypes.NewValue(tftypes.String, `{ "keys": [{"kty":"RSA","kid":"old"}] }`),
				"computed": tftypes.NewValue(tftypes.String, "assigned"),
			})
			for label, tc := range map[string]struct {
				doc  string
				want bool
			}{
				"formatting only":    {`{"keys":[{"kid":"old","kty":"RSA"}]}`, true},
				"rotated key":        {`{"keys":[{"kid":"new","kty":"RSA"}]}`, false},
				"removed key":        {`{"keys":[]}`, false},
				"malformed document": {`invalid`, false},
			} {
				t.Run(label, func(t *testing.T) {
					plan := obj(types, map[string]tftypes.Value{
						name:       tftypes.NewValue(tftypes.String, tc.doc),
						"computed": tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
					})
					if got := onlyUnknownsDiffer(plan, state); got != tc.want {
						t.Fatalf("same plan = %v, want %v", got, tc.want)
					}
				})
			}
		})
	}
}

func obj(fields map[string]tftypes.Type, values map[string]tftypes.Value) tftypes.Value {
	return tftypes.NewValue(tftypes.Object{AttributeTypes: fields}, values)
}

// The rule: a plan that differs from prior state only by unknowns is not a
// change. Anything known and different is.
func TestOnlyUnknownsDiffer(t *testing.T) {
	types := map[string]tftypes.Type{
		"name":   tftypes.String,
		"count":  tftypes.Number,
		"things": tftypes.List{ElementType: tftypes.String},
	}
	list := func(vals ...string) tftypes.Value {
		out := make([]tftypes.Value, 0, len(vals))
		for _, v := range vals {
			out = append(out, tftypes.NewValue(tftypes.String, v))
		}
		return tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, out)
	}
	state := obj(types, map[string]tftypes.Value{
		"name":   tftypes.NewValue(tftypes.String, "a"),
		"count":  tftypes.NewValue(tftypes.Number, 1),
		"things": list("x", "y"),
	})

	for name, tc := range map[string]struct {
		plan tftypes.Value
		want bool
	}{
		"identical": {state, true},
		"a computed attribute went unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": list("x", "y"),
		}), true},
		"every attribute went unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, tftypes.UnknownValue),
		}), true},
		"a real edit to a string": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "b"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y"),
		}), false},
		"a real edit alongside an unknown": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "b"),
			"count":  tftypes.NewValue(tftypes.Number, tftypes.UnknownValue),
			"things": list("x", "y"),
		}), false},
		// The ordering modifiers run before this, so a list Authlete reorders
		// already matches. One that still differs genuinely moved.
		"a list that still differs": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("y", "x"),
		}), false},
		"an element added": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, "a"),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y", "z"),
		}), false},
		"a value became null": {obj(types, map[string]tftypes.Value{
			"name":   tftypes.NewValue(tftypes.String, nil),
			"count":  tftypes.NewValue(tftypes.Number, 1),
			"things": list("x", "y"),
		}), false},
	} {
		t.Run(name, func(t *testing.T) {
			if got := onlyUnknownsDiffer(tc.plan, state); got != tc.want {
				t.Errorf("onlyUnknownsDiffer = %v, want %v", got, tc.want)
			}
		})
	}
}

// Nested objects are where the computed attributes of a client's extension
// live, so the walk has to reach them.
func TestOnlyUnknownsDiffersWalksNested(t *testing.T) {
	inner := tftypes.Object{AttributeTypes: map[string]tftypes.Type{"n": tftypes.Number}}
	outer := map[string]tftypes.Type{"ext": inner}

	state := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, 1)}),
	})
	unknownInside := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, tftypes.UnknownValue)}),
	})
	changedInside := obj(outer, map[string]tftypes.Value{
		"ext": tftypes.NewValue(inner, map[string]tftypes.Value{"n": tftypes.NewValue(tftypes.Number, 2)}),
	})

	if !onlyUnknownsDiffer(unknownInside, state) {
		t.Error("a nested unknown should not count as a change")
	}
	if onlyUnknownsDiffer(changedInside, state) {
		t.Error("a nested edit was missed, so a real change would be suppressed")
	}
}

// An unknown the framework invented is noise. An unknown the user wrote is a
// change the provider cannot see yet, and absorbing it loses that change
// silently. The case that matters is jwks built from a tls_private_key being
// created in the same run, which is the rotation the migration guide
// recommends: the plan said "No changes" and the keys were never rotated.
func TestAConfiguredUnknownIsNotAbsorbed(t *testing.T) {
	types := map[string]tftypes.Type{
		"name": tftypes.String,
		"jwks": tftypes.String,
	}
	state := obj(types, map[string]tftypes.Value{
		"name": tftypes.NewValue(tftypes.String, "svc"),
		"jwks": tftypes.NewValue(tftypes.String, "old-keys"),
	})
	// jwks comes from a resource being created, so it is unknown at plan time.
	plan := obj(types, map[string]tftypes.Value{
		"name": tftypes.NewValue(tftypes.String, "svc"),
		"jwks": tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
	})

	// Without looking at the configuration, the plan and prior state differ
	// only by an unknown, so the old rule absorbed it.
	if !onlyUnknownsDiffer(plan, state) {
		t.Fatal("precondition: this is exactly the shape the old rule absorbed")
	}

	configured := obj(types, map[string]tftypes.Value{
		"name": tftypes.NewValue(tftypes.String, "svc"),
		"jwks": tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
	})
	if !containsUnknown(configured) {
		t.Fatal("a configuration holding an unknown must be recognised as such")
	}

	// And a configuration with nothing unknown must not stand the rule down,
	// or the reorder fix stops working.
	settled := obj(types, map[string]tftypes.Value{
		"name": tftypes.NewValue(tftypes.String, "svc"),
		"jwks": tftypes.NewValue(tftypes.String, nil),
	})
	if containsUnknown(settled) {
		t.Fatal("a fully known configuration must not stand the rule down")
	}
}

// Nested, because a client's extension attributes live inside an object and a
// jwks built from a new key can sit anywhere in the tree.
func TestContainsUnknownFindsItNested(t *testing.T) {
	inner := tftypes.Object{AttributeTypes: map[string]tftypes.Type{"kid": tftypes.String}}
	outer := map[string]tftypes.Type{
		"name":      tftypes.String,
		"extension": inner,
		"list":      tftypes.List{ElementType: tftypes.String},
	}

	known := obj(outer, map[string]tftypes.Value{
		"name": tftypes.NewValue(tftypes.String, "c"),
		"extension": tftypes.NewValue(inner, map[string]tftypes.Value{
			"kid": tftypes.NewValue(tftypes.String, "k1"),
		}),
		"list": tftypes.NewValue(tftypes.List{ElementType: tftypes.String},
			[]tftypes.Value{tftypes.NewValue(tftypes.String, "a")}),
	})
	if containsUnknown(known) {
		t.Fatal("nothing here is unknown")
	}

	for name, v := range map[string]tftypes.Value{
		"inside an object": obj(outer, map[string]tftypes.Value{
			"name": tftypes.NewValue(tftypes.String, "c"),
			"extension": tftypes.NewValue(inner, map[string]tftypes.Value{
				"kid": tftypes.NewValue(tftypes.String, tftypes.UnknownValue),
			}),
			"list": tftypes.NewValue(tftypes.List{ElementType: tftypes.String}, nil),
		}),
		"inside a list": obj(outer, map[string]tftypes.Value{
			"name":      tftypes.NewValue(tftypes.String, "c"),
			"extension": tftypes.NewValue(inner, nil),
			"list": tftypes.NewValue(tftypes.List{ElementType: tftypes.String},
				[]tftypes.Value{tftypes.NewValue(tftypes.String, tftypes.UnknownValue)}),
		}),
	} {
		if !containsUnknown(v) {
			t.Fatalf("an unknown %s must be found", name)
		}
	}
}
